import json, os, glob

# Collect all pairwise_auc.json files and extract 1v2 and 2v3 fold data
results = {}
for f in sorted(glob.glob('results/*/pairwise_auc.json') + glob.glob('results_*/pairwise_auc.json')):
    config = f.split('/')[1] if f.startswith('results/') else f.split('/')[0]
    if config.startswith('results_'):
        config = config.replace('results_', '')
    d = json.load(open(f))
    entry = {}
    if 'per_fold' in d:
        for pair in ['1v2', '2v3']:
            if pair in d['per_fold']:
                entry[pair] = {'mean': d['mean'][pair], 'folds': d['per_fold'][pair]}
    results[config] = entry

print(json.dumps(results, indent=2))
"
